import { memo } from "preact/compat";
import { useEffect, useRef } from "preact/hooks";
import type { editor as MonacoEditorNs, IDisposable } from "monaco-editor";
import type { MonacoNamespace } from "@/features/editor/lib/monacoCore";
import type { LanguageId } from "@/shared/types/language";
import { LANGUAGES } from "@/shared/types/language";
import { ensureMonacoEnvironment } from "@/features/editor/lib/monacoEnvironment";
import type { ThemeMode } from "@/ui/tokens";

interface MonacoEditorProps {
  value: string;
  language: LanguageId;
  fontSize: number;
  theme: ThemeMode;
  onChange: (value: string) => void;
}

function toMonacoTheme(theme: ThemeMode): string {
  return theme === "dark" ? "leetify-dark" : "vs";
}

let themesDefined = false;

/**
 * Custom dark theme matching the workspace palette: editor sits on the
 * panel layer (#262626) with a #2d2d2d gutter band (reads as a faint
 * divider), muted line numbers, and a barely-there active-line tint.
 */
function ensureEditorThemes(monaco: MonacoNamespace) {
  if (themesDefined) return;
  themesDefined = true;
  monaco.editor.defineTheme("leetify-dark", {
    base: "vs-dark",
    inherit: true,
    rules: [],
    colors: {
      "editor.background": "#262626",
      "editor.foreground": "#e0e0e0",
      "editor.lineHighlightBackground": "#2d2d2d",
      "editorGutter.background": "#2d2d2d",
      "editorLineNumber.foreground": "#6a6a6a",
      "editorLineNumber.activeForeground": "#a8a8a8",
      "editorIndentGuide.background1": "#3e3e3e",
      "editorCursor.foreground": "#e0e0e0",
      "editor.selectionBackground": "#3e4a5b",
      "editorWidget.background": "#2d2d2d",
      "editorWidget.border": "#3e3e3e",
      "scrollbarSlider.background": "#3e3e3e80",
      "scrollbarSlider.hoverBackground": "#3e3e3ecc",
    },
  });
}

/**
 * Vite's dynamic-import CSS injection always targets document.head, with
 * no awareness of shadow DOM. Since we mount inside a shadow root, that
 * stylesheet loads successfully but has zero effect there — shadow trees
 * don't inherit light-DOM stylesheets, so structural rules Monaco depends
 * on (e.g. `.overflow-guard { position: relative }`) silently never
 * apply, leaving Monaco's internal absolutely-positioned layers to escape
 * to viewport-root coordinates instead of their intended container.
 * Moving (not cloning) the injected <link> into our own root fixes this
 * without duplicating the stylesheet.
 */
function relocateMonacoStylesheets(containerEl: Element) {
  const root = containerEl.getRootNode();
  if (!(root instanceof ShadowRoot)) return;
  const stray = document.head.querySelectorAll<HTMLLinkElement>(
    'link[rel="stylesheet"][href*="monacoCore"]'
  );
  stray.forEach((link) => root.appendChild(link));
}

// Memoized: the editor manages its content imperatively; the wrapper only
// re-renders when one of these props actually changes, never merely
// because an ancestor re-rendered.
export const MonacoEditor = memo(MonacoEditorImpl);

function MonacoEditorImpl({
  value,
  language,
  fontSize,
  theme,
  onChange,
}: MonacoEditorProps) {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const editorRef = useRef<MonacoEditorNs.IStandaloneCodeEditor | null>(null);
  const onChangeRef = useRef(onChange);
  onChangeRef.current = onChange;
  // Latest props, updated every render. Editor creation is async (dynamic
  // import) — by the time it resolves, props may have advanced past the
  // mount-render closure (e.g. store hydration landing with saved code
  // and a different language). The per-prop effects below skip while
  // editorRef is null and their deps won't change again afterwards, so
  // the editor MUST be created from the latest props, not captured ones —
  // otherwise a reload shows the stale first-render value forever.
  const propsRef = useRef({ value, language, fontSize, theme });
  propsRef.current = { value, language, fontSize, theme };

  useEffect(() => {
    let disposed = false;
    let disposable: IDisposable | undefined;

    (async () => {
      ensureMonacoEnvironment();
      const { monaco } = await import("@/features/editor/lib/monacoCore");
      if (disposed || !containerRef.current) return;

      relocateMonacoStylesheets(containerRef.current);
      ensureEditorThemes(monaco);

      const latest = propsRef.current;
      const editor = monaco.editor.create(containerRef.current, {
        value: latest.value,
        language: LANGUAGES[latest.language].monacoId,
        fontSize: latest.fontSize,
        theme: toMonacoTheme(latest.theme),
        automaticLayout: true,
        minimap: { enabled: false },
        scrollBeyondLastLine: false,
        smoothScrolling: true,
        padding: { top: 12, bottom: 12 },
        fontFamily: "'Fira Code', Menlo, Consolas, monospace",
        fontLigatures: true,
        lineNumbersMinChars: 3,
        // Monaco draws its own scrollbar to canvas (unreachable by CSS);
        // default is a chunky 14px with arrows. Slim + shadowless matches
        // the workspace's minimal scrollbars.
        scrollbar: {
          verticalScrollbarSize: 8,
          horizontalScrollbarSize: 8,
          useShadows: false,
        },
        // Monaco ships a full IDE feature set that recomputes on every
        // keystroke — autocomplete, word-based suggestions, occurrence &
        // selection highlighting, folding, CodeLens, link/hover detection,
        // bracket-pair colorization, sticky scroll. A CSES solve needs
        // fast editing + syntax highlighting; leaving these on was the
        // bulk of the measured per-keystroke CPU cost.
        quickSuggestions: false,
        suggestOnTriggerCharacters: false,
        wordBasedSuggestions: "off",
        parameterHints: { enabled: false },
        occurrencesHighlight: "off",
        selectionHighlight: false,
        folding: false,
        codeLens: false,
        links: false,
        hover: { enabled: false },
        inlayHints: { enabled: "off" },
        stickyScroll: { enabled: false },
        bracketPairColorization: { enabled: false },
        matchBrackets: "never",
        renderValidationDecorations: "off",
      });
      editorRef.current = editor;
      disposable = editor.onDidChangeModelContent(() => {
        onChangeRef.current(editor.getValue());
      });

      // Defensive: force one more re-layout after a real paint, in case
      // anything about the container's box wasn't fully settled at the
      // exact moment create() ran its own synchronous measurement.
      requestAnimationFrame(() => {
        if (!disposed) editor.layout();
      });
    })().catch((error) => {
      console.error("[Leetify for CSES] Failed to mount Monaco editor", error);
    });

    return () => {
      disposed = true;
      disposable?.dispose();
      editorRef.current?.dispose();
      editorRef.current = null;
    };
    // Editor is created once per mount; language/value swaps for the same
    // instance are handled by the effects below.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    const editor = editorRef.current;
    if (!editor) return;
    if (editor.getValue() !== value) {
      editor.setValue(value);
    }
  }, [value]);

  useEffect(() => {
    // Skip until the editor exists; the create path already sets the
    // initial language, and importing monacoCore here before creation
    // would just duplicate work.
    if (!editorRef.current) return;
    import("@/features/editor/lib/monacoCore").then(({ monaco }) => {
      const model = editorRef.current?.getModel();
      if (model) monaco.editor.setModelLanguage(model, LANGUAGES[language].monacoId);
    });
  }, [language]);

  useEffect(() => {
    editorRef.current?.updateOptions({ fontSize });
  }, [fontSize]);

  useEffect(() => {
    const editor = editorRef.current;
    if (!editor) return;
    import("@/features/editor/lib/monacoCore").then(({ monaco }) => {
      ensureEditorThemes(monaco);
      monaco.editor.setTheme(toMonacoTheme(theme));
      // setTheme() updates computed styles correctly but can leave a
      // stale paint behind in this shadow-DOM setup; force a repaint.
      editor.render(true);
    });
  }, [theme]);

  return <div ref={containerRef} className="h-full w-full" />;
}
