import { storageGet, storageRemove, storageSet } from "@/storage/chromeStorage";
import type { LanguageId } from "@/shared/types/language";

export interface PendingSubmission {
  taskId: string;
  code: string;
  language: LanguageId;
  createdAt: number;
}

const KEY = "leetify:pendingSubmission";

/** Stashes code across the navigation to CSES's native submit page (see submitAutofill.ts). */
export async function setPendingSubmission(sub: PendingSubmission): Promise<void> {
  await storageSet(KEY, sub);
}

/** Reads and clears the pending submission — one-shot, so a stale one can't silently reapply later. */
export async function takePendingSubmission(): Promise<PendingSubmission | null> {
  const sub = await storageGet<PendingSubmission>(KEY);
  if (sub) await storageRemove(KEY);
  return sub ?? null;
}
