import { useLayoutEffect, useRef, useState } from "preact/hooks";

interface TabDef {
  id: string;
  label: string;
}

interface TabsProps {
  tabs: TabDef[];
  activeId: string;
  onChange: (id: string) => void;
  className?: string;
}

/**
 * LeetCode-style tabs: the active tab is marked by an accent underline
 * that slides between tabs (~150ms ease) rather than jumping.
 */
export function Tabs({ tabs, activeId, onChange, className = "" }: TabsProps) {
  const listRef = useRef<HTMLDivElement | null>(null);
  const [indicator, setIndicator] = useState({ left: 0, width: 0 });

  useLayoutEffect(() => {
    const list = listRef.current;
    if (!list) return;

    const measure = () => {
      const active = list.querySelector<HTMLElement>(
        `[data-tab-id="${activeId}"]`
      );
      if (!active) return;
      const next = { left: active.offsetLeft, width: active.offsetWidth };
      setIndicator((prev) =>
        prev.left === next.left && prev.width === next.width ? prev : next
      );
    };

    measure();
    // The shadow root's stylesheet <link> loads async, so the first
    // measurement can run before layout styles apply (wrong offsets that
    // would otherwise stick). A ResizeObserver on the list re-measures
    // when the late CSS reflows it — and also when panel resizing
    // rewraps the tabs.
    const observer = new ResizeObserver(measure);
    observer.observe(list);
    return () => observer.disconnect();
    // Re-measure when the tab set changes too (labels shift positions).
  }, [activeId, tabs.map((t) => t.id).join("|")]);

  return (
    <div
      ref={listRef}
      role="tablist"
      className={`relative flex items-center gap-5 ${className}`}
    >
      {tabs.map((tab) => {
        const active = tab.id === activeId;
        return (
          <button
            key={tab.id}
            data-tab-id={tab.id}
            onClick={() => onChange(tab.id)}
            aria-selected={active}
            role="tab"
            className={`px-0.5 py-2.5 text-[13px] font-medium transition-colors duration-DEFAULT ${
              active ? "text-fg" : "text-fg-muted hover:text-fg"
            }`}
          >
            {tab.label}
          </button>
        );
      })}
      <span
        aria-hidden="true"
        className="absolute bottom-0 h-[2px] rounded-full bg-accent transition-all duration-150 ease-out"
        style={{ left: `${indicator.left}px`, width: `${indicator.width}px` }}
      />
    </div>
  );
}
