import { create } from "zustand";
import type { RunCaseResult } from "@/extension/messaging/types";

export type RunStatus = "idle" | "running";

interface RunResultsState {
  status: RunStatus;
  /**
   * Which task the current compileError/infraError/resultsByCase belong
   * to. TestPanel gates on this matching the task it's rendering rather
   * than clearing resultsByCase on every task switch — a stale case
   * result for a different task's case id simply never gets looked up,
   * but a batch-wide compileError/infraError needs this to avoid a
   * switched-to task silently showing a previous task's failure.
   */
  lastRunTaskId: string | null;
  compileError: string | null;
  /** Judge/proxy unreachable, distinct from a real compile error. */
  infraError: string | null;
  resultsByCase: Record<string, RunCaseResult>;
  startRun: (taskId: string) => void;
  setResults: (taskId: string, compileError: string | null, results: RunCaseResult[]) => void;
  setInfraError: (taskId: string, message: string) => void;
}

/**
 * Run results live in their own tiny, non-persisted store (mirrors
 * autosaveStore.ts) so a run updates only the "Test Result" tab's
 * subscribers, not the whole editor pane. Resets on reload — that's
 * intentional, a run result is a point-in-time judge response, not
 * something worth persisting across sessions.
 */
export const useRunResultsStore = create<RunResultsState>((set) => ({
  status: "idle",
  lastRunTaskId: null,
  compileError: null,
  infraError: null,
  resultsByCase: {},
  startRun: (taskId) =>
    set({ status: "running", lastRunTaskId: taskId, compileError: null, infraError: null }),
  setResults: (taskId, compileError, results) =>
    set((s) => ({
      status: "idle",
      lastRunTaskId: taskId,
      compileError,
      infraError: null,
      resultsByCase: {
        ...s.resultsByCase,
        ...Object.fromEntries(results.map((r) => [r.caseId, r])),
      },
    })),
  setInfraError: (taskId, message) =>
    set({ status: "idle", lastRunTaskId: taskId, compileError: null, infraError: message }),
}));
