/**
 * A one-way fingerprint of the user's CSES session, used only to give
 * the judge Worker's per-install Run quota real Sybil-resistance (see
 * docs/DEVELOPMENT_LOG.md — a self-generated random install ID costs
 * nothing to regenerate; a fresh CSES login does not).
 *
 * CSES's session cookie (`PHPSESSID`) is not `HttpOnly`, so it's
 * technically readable here — but the actual cookie value is never sent
 * anywhere. Only a SHA-256 hash of it is, and only from this
 * content-script context (`document.cookie` isn't available in the
 * background service worker). Deliberately not used for anything beyond
 * this: no server-side verification that a hash corresponds to a
 * currently-valid session, no attempt to authenticate the user to CSES
 * on their behalf.
 */
export async function getCsesSessionHash(): Promise<string | null> {
  const match = document.cookie.match(/(?:^|;\s*)PHPSESSID=([^;]+)/);
  if (!match) return null;

  const bytes = new TextEncoder().encode(match[1]);
  const digest = await crypto.subtle.digest("SHA-256", bytes);
  return Array.from(new Uint8Array(digest))
    .map((b) => b.toString(16).padStart(2, "0"))
    .join("");
}
