import { LANGUAGES, type LanguageId } from "@/shared/types/language";
import {
  setPendingSubmission,
  takePendingSubmission,
  type PendingSubmission,
} from "@/shared/services/storage/pendingSubmission";

/**
 * CSES's own "Submit" tab is a normal nav link to a separate page — we
 * don't know its URL pattern in advance (it varies: /problemset/task/…
 * for the public set, course-specific prefixes elsewhere), so we find the
 * real link CSES already rendered rather than guessing a URL to build.
 *
 * mount.tsx removes the original `.navigation` band once its data has
 * been re-rendered into the workspace's own header (see
 * extractTitleBlock in findProblemContent.ts) — by the time a user can
 * actually click Submit, that DOM node is long gone. rememberSubmitHref
 * caches the href at mount time, before removal, so this doesn't have to
 * re-query a node we know we deleted. The live DOM query remains as a
 * fallback for the case where mount never ran the removal (pageMeta was
 * null, so `.navigation` is still there) or ran in a context this module
 * didn't observe.
 */
let cachedSubmitHref: string | null = null;

export function rememberSubmitHref(href: string | null): void {
  cachedSubmitHref = href;
}

function findNativeSubmitLink(): { href: string } | null {
  if (cachedSubmitHref) return { href: cachedSubmitHref };
  const links = Array.from(
    document.querySelectorAll<HTMLAnchorElement>(".navigation .nav a")
  );
  const link = links.find((a) => a.textContent?.trim().toLowerCase() === "submit");
  return link ? { href: link.href } : null;
}

/**
 * Stashes the current code and navigates to CSES's native submit page.
 * Returns false (and does nothing) if the Submit tab isn't on the page —
 * e.g. the user isn't logged in, so CSES doesn't render it.
 */
export async function navigateToNativeSubmit(
  sub: PendingSubmission
): Promise<boolean> {
  const link = findNativeSubmitLink();
  if (!link) return false;
  await setPendingSubmission(sub);
  window.location.href = link.href;
  return true;
}

function scoreLanguageOption(optionText: string, language: LanguageId): number {
  const t = optionText.toLowerCase();
  switch (language) {
    case "cpp":
      return t.includes("c++") ? 2 : 0;
    case "c":
      return t.includes("c") && !t.includes("c++") && !t.includes("c#") ? 1 : 0;
    case "python":
      return t.includes("python") ? 2 : 0;
    case "java":
      return t.includes("java") && !t.includes("javascript") ? 2 : 0;
  }
}

/**
 * Runs on every CSES page load and is a no-op unless both (a) this page
 * looks like the submit form — feature-detected via a file input, since
 * we don't know the URL — and (b) there's a pending submission stashed
 * for it. Fills in the code file and best-guesses the language dropdown
 * by matching visible option text (exact option values are unknown
 * without an authenticated session to inspect) — deliberately does NOT
 * auto-click the real submit button, leaving that action to the user.
 */
export async function runSubmitAutofill(): Promise<void> {
  const fileInput = document.querySelector<HTMLInputElement>('input[type="file"]');
  if (!fileInput) return;

  const pending = await takePendingSubmission();
  if (!pending) return;

  const ext = LANGUAGES[pending.language].fileExtension;
  const file = new File([pending.code], `submission.${ext}`, {
    type: "text/plain",
  });
  const dataTransfer = new DataTransfer();
  dataTransfer.items.add(file);
  fileInput.files = dataTransfer.files;
  fileInput.dispatchEvent(new Event("change", { bubbles: true }));

  const select = document.querySelector<HTMLSelectElement>("select");
  if (!select) return;

  let best: HTMLOptionElement | undefined;
  let bestScore = 0;
  for (const option of Array.from(select.options)) {
    const score = scoreLanguageOption(option.text, pending.language);
    if (score > bestScore) {
      bestScore = score;
      best = option;
    }
  }
  if (best) {
    select.value = best.value;
    select.dispatchEvent(new Event("change", { bubbles: true }));
  }
}
