export interface SampleTest {
  input: string;
  output: string;
}

/**
 * CSES embeds sample tests directly in the problem statement as
 * alternating `<p>Input:</p><pre>…</pre>` / `<p>Output:</p><pre>…</pre>`
 * pairs following an "Example" heading — harder problems repeat the
 * pattern for multiple examples. Pairing consecutive <pre> elements
 * (rather than parsing the "Input:"/"Output:" label text) is robust to
 * that repetition without needing to special-case example count.
 */
export function parseSampleTests(problemNode: Element | null): SampleTest[] {
  if (!problemNode) return [];
  const pres = Array.from(problemNode.querySelectorAll("pre"));
  const tests: SampleTest[] = [];
  for (let i = 0; i + 1 < pres.length; i += 2) {
    const input = pres[i]?.textContent?.trim() ?? "";
    const output = pres[i + 1]?.textContent?.trim() ?? "";
    if (input || output) tests.push({ input, output });
  }
  return tests;
}
