import { useAutosaveStore, type AutosaveStatus } from "@/state/autosaveStore";

const LABELS: Record<AutosaveStatus, string> = {
  idle: "",
  saving: "Saving…",
  saved: "Saved",
};

/**
 * Self-subscribes to the autosave store so this tiny label is the ONLY
 * thing that re-renders while typing — the editor pane stays out of the
 * per-keystroke render path.
 */
export function AutosaveIndicator() {
  const status = useAutosaveStore((s) => s.status);
  if (status === "idle") return null;
  return (
    <span className="text-[12px] text-fg-subtle transition-opacity duration-DEFAULT">
      {LABELS[status]}
    </span>
  );
}
