import { create } from "zustand";
import { persist } from "zustand/middleware";
import { createChromeStoragePersister } from "@/shared/services/storage/zustandChromeStorage";
import { DEFAULT_LANGUAGE, type LanguageId } from "@/shared/types/language";
import { EDITOR_FONT_SIZE_DEFAULT } from "@/ui/tokens";

export interface EditorSnapshot {
  code: string;
  updatedAt: number;
}

/**
 * Exported so components can subscribe to a single snapshot directly
 * (`s.snapshots[snapshotKey(...)]`) — a reference-stable selection that
 * both re-renders on hydration/merge and lets callers distinguish "never
 * touched" (undefined) from "intentionally emptied" (code === "").
 */
export function snapshotKey(taskId: string, language: LanguageId): string {
  return `${taskId}:${language}`;
}

interface EditorState {
  language: LanguageId;
  fontSize: number;
  snapshots: Record<string, EditorSnapshot>;
  setLanguage: (language: LanguageId) => void;
  setFontSize: (size: number) => void;
  getCode: (taskId: string, language: LanguageId) => string;
  setCode: (taskId: string, language: LanguageId, code: string) => void;
}

export const useEditorStore = create<EditorState>()(
  persist(
    (set, get) => ({
      language: DEFAULT_LANGUAGE,
      fontSize: EDITOR_FONT_SIZE_DEFAULT,
      snapshots: {},
      setLanguage: (language) => set({ language }),
      setFontSize: (fontSize) => set({ fontSize }),
      getCode: (taskId, language) =>
        get().snapshots[snapshotKey(taskId, language)]?.code ?? "",
      setCode: (taskId, language, code) =>
        set((s) => ({
          snapshots: {
            ...s.snapshots,
            [snapshotKey(taskId, language)]: { code, updatedAt: Date.now() },
          },
        })),
    }),
    {
      name: "leetify:editor",
      storage: createChromeStoragePersister(),
      // Async rehydration races any setCode that happens right after mount
      // (e.g. typing immediately on page load): the default shallow merge
      // would replace the WHOLE snapshots map with the persisted one,
      // silently discarding the newer write. Merge per-key; keep the
      // fresher entry when both sides have the same task+language.
      merge: (persisted, current) => {
        const p = (persisted ?? {}) as Partial<EditorState>;
        const merged: Record<string, EditorSnapshot> = {
          ...current.snapshots,
        };
        for (const [key, snap] of Object.entries(p.snapshots ?? {})) {
          const existing = merged[key];
          if (!existing || snap.updatedAt >= existing.updatedAt) {
            merged[key] = snap;
          }
        }
        return { ...current, ...p, snapshots: merged };
      },
    }
  )
);
