import { SplitPane } from "@/features/layout/components/SplitPane";
import { ProblemPane } from "@/features/layout/components/ProblemPane";
import { WorkspaceHeader } from "@/features/layout/components/WorkspaceHeader";
import { EditorPanel } from "@/features/editor/components/EditorPanel";
import { useWorkspaceStore } from "@/state/workspaceStore";
import type { TitleBlockMeta } from "@/extension/content/findProblemContent";

interface WorkspaceProps {
  taskId: string;
  problemNode: Element | null;
  topicLabel: string;
  topicNode: Element | null;
  submissionsNode: Element | null;
  /** Title/nav data lifted from CSES's removed `.title-block` band; null if its markup changed. */
  pageMeta: TitleBlockMeta | null;
  /** Distance from the page top to where the workspace naturally sits, measured once at mount. */
  topOffsetPx: number;
}

export function Workspace({
  taskId,
  problemNode,
  topicLabel,
  topicNode,
  submissionsNode,
  pageMeta,
  topOffsetPx,
}: WorkspaceProps) {
  const splitPercent = useWorkspaceStore((s) => s.splitPercent);
  const setSplitPercent = useWorkspaceStore((s) => s.setSplitPercent);
  // CSES only renders a "Submit" nav link when the user is logged in
  // (logged-out pages carry Task/Statistics instead) — this is CSES's
  // own signal, read from the same title-block data already extracted
  // for WorkspaceHeader, not a cookie/session check of our own.
  const isLoggedIn =
    pageMeta?.navLinks.some((l) => l.label.trim().toLowerCase() === "submit") ?? false;

  return (
    // Sized to the actual remaining viewport below CSES's own header/nav
    // (not a flat 100vh, which would overflow past the fold by
    // topOffsetPx) so the full workspace is visible immediately on load.
    // Sticky keeps it pinned to the top as the page scrolls — this
    // doubles as Phase 1's "sticky editor" requirement.
    <div
      style={{ height: `calc(100vh - ${topOffsetPx}px)` }}
      className="sticky top-0 flex w-full flex-col overflow-hidden bg-bg-base text-fg"
    >
      {pageMeta && <WorkspaceHeader meta={pageMeta} />}
      <div className="min-h-0 flex-1">
        <SplitPane
          splitPercent={splitPercent}
          onSplitChange={setSplitPercent}
          left={
            <ProblemPane
              problemNode={problemNode}
              topicLabel={topicLabel}
              topicNode={topicNode}
              submissionsNode={submissionsNode}
            />
          }
          right={
            <EditorPanel taskId={taskId} problemNode={problemNode} isLoggedIn={isLoggedIn} />
          }
        />
      </div>
    </div>
  );
}
