import { Toolbar } from "@/features/layout/components/Toolbar";
import { Select } from "@/shared/components/Select";
import { IconButton } from "@/shared/components/IconButton";
import { Button } from "@/shared/components/Button";
import { PlayIcon, CheckIcon, SunIcon, MoonIcon } from "@/shared/components/icons";
import { AutosaveIndicator } from "@/features/editor/components/AutosaveIndicator";
import { LANGUAGE_LIST, type LanguageId } from "@/shared/types/language";
import { useWorkspaceStore } from "@/state/workspaceStore";
import {
  EDITOR_FONT_SIZE_MAX,
  EDITOR_FONT_SIZE_MIN,
} from "@/ui/tokens";

interface EditorToolbarProps {
  language: LanguageId;
  onLanguageChange: (language: LanguageId) => void;
  fontSize: number;
  onFontSizeChange: (size: number) => void;
  onRun: () => void;
  onSubmit: () => void;
  isLoggedIn: boolean;
  running: boolean;
  submitting: boolean;
}

export function EditorToolbar({
  language,
  onLanguageChange,
  fontSize,
  onFontSizeChange,
  onRun,
  onSubmit,
  isLoggedIn,
  running,
  submitting,
}: EditorToolbarProps) {
  const theme = useWorkspaceStore((s) => s.theme);
  const toggleTheme = useWorkspaceStore((s) => s.toggleTheme);

  return (
    <Toolbar
      left={
        <Select
          ariaLabel="Language"
          value={language}
          onChange={onLanguageChange}
          options={LANGUAGE_LIST.map((l) => ({ value: l.id, label: l.label }))}
        />
      }
      right={
        <>
          <AutosaveIndicator />
          {/* Font-size stepper as a compact segmented control. */}
          <div className="flex items-center rounded-md bg-bg-overlay p-0.5">
            <button
              aria-label="Decrease font size"
              disabled={fontSize <= EDITOR_FONT_SIZE_MIN}
              onClick={() => onFontSizeChange(fontSize - 1)}
              className="h-6 w-6 rounded text-[13px] text-fg-muted transition-colors duration-100 hover:bg-border hover:text-fg disabled:opacity-40"
            >
              −
            </button>
            <span className="w-7 text-center text-[12px] tabular-nums text-fg-muted">
              {fontSize}
            </span>
            <button
              aria-label="Increase font size"
              disabled={fontSize >= EDITOR_FONT_SIZE_MAX}
              onClick={() => onFontSizeChange(fontSize + 1)}
              className="h-6 w-6 rounded text-[13px] text-fg-muted transition-colors duration-100 hover:bg-border hover:text-fg disabled:opacity-40"
            >
              +
            </button>
          </div>
          <IconButton
            label={theme === "dark" ? "Switch to light theme" : "Switch to dark theme"}
            onClick={toggleTheme}
          >
            {theme === "dark" ? (
              <SunIcon className="h-4 w-4" />
            ) : (
              <MoonIcon className="h-4 w-4" />
            )}
          </IconButton>
          <div className="mx-1 h-5 w-px bg-border-subtle" />
          <Button
            variant="subtle"
            onClick={onRun}
            disabled={running || submitting || !isLoggedIn}
            title={isLoggedIn ? undefined : "Log in to CSES to use Run"}
          >
            <PlayIcon className="h-3.5 w-3.5" />
            {running ? "Running…" : "Run"}
          </Button>
          <Button
            variant="primary"
            onClick={onSubmit}
            disabled={submitting || running || !isLoggedIn}
            title={isLoggedIn ? undefined : "Log in to CSES to submit"}
          >
            <CheckIcon className="h-3.5 w-3.5" />
            {submitting ? "Submitting…" : "Submit"}
          </Button>
        </>
      }
    />
  );
}
