import { useCallback, useRef, useState } from "preact/hooks";
import { PANEL_MIN_WIDTH_PX } from "@/ui/tokens";

interface UsePanelResizeArgs {
  containerRef: { current: HTMLElement | null };
  /** Fires once, at drag end — not per pointermove — since onCommit is expected to persist. */
  onCommit: (percent: number) => void;
}

/** Drag-to-resize handler for a two-pane split layout, clamped to a minimum panel width. */
export function usePanelResize({ containerRef, onCommit }: UsePanelResizeArgs) {
  // Live value while dragging only. Writing every pointermove straight to
  // the persisted store would fire a chrome.storage write per event —
  // tens per second — which is the real cost, not the re-render.
  const [dragPercent, setDragPercent] = useState<number | null>(null);
  // Kept in sync synchronously, independent of the rAF-throttled
  // re-render below — stopDragging reads this, so a drag that ends
  // between frames still commits the latest position.
  const dragPercentRef = useRef<number | null>(null);
  const rafRef = useRef<number | null>(null);
  const onCommitRef = useRef(onCommit);
  onCommitRef.current = onCommit;

  const handlePointerMove = useCallback(
    (event: PointerEvent) => {
      if (!containerRef.current) return;
      const rect = containerRef.current.getBoundingClientRect();
      const offsetX = event.clientX - rect.left;
      const minPercent = (PANEL_MIN_WIDTH_PX / rect.width) * 100;
      const percent = (offsetX / rect.width) * 100;
      const clamped = Math.min(100 - minPercent, Math.max(minPercent, percent));
      dragPercentRef.current = clamped;
      if (rafRef.current !== null) return;
      rafRef.current = requestAnimationFrame(() => {
        rafRef.current = null;
        setDragPercent(dragPercentRef.current);
      });
    },
    [containerRef]
  );

  const stopDragging = useCallback(() => {
    document.removeEventListener("pointermove", handlePointerMove);
    document.removeEventListener("pointerup", stopDragging);
    document.body.style.cursor = "";
    document.body.style.userSelect = "";
    if (rafRef.current !== null) {
      cancelAnimationFrame(rafRef.current);
      rafRef.current = null;
    }
    if (dragPercentRef.current !== null) {
      onCommitRef.current(dragPercentRef.current);
    }
    dragPercentRef.current = null;
    setDragPercent(null);
  }, [handlePointerMove]);

  const startDragging = useCallback(
    (event: PointerEvent) => {
      event.preventDefault();
      document.addEventListener("pointermove", handlePointerMove);
      document.addEventListener("pointerup", stopDragging);
      document.body.style.cursor = "col-resize";
      document.body.style.userSelect = "none";
    },
    [handlePointerMove, stopDragging]
  );

  return { dragPercent, startDragging };
}
