import { create } from "zustand";

export type AutosaveStatus = "idle" | "saving" | "saved";

interface AutosaveState {
  status: AutosaveStatus;
  setStatus: (status: AutosaveStatus) => void;
}

/**
 * Autosave status lives in its own tiny, non-persisted store so a
 * keystroke updates ONLY the small indicator that subscribes here — not
 * the whole editor pane. When this was plain useState consumed high in
 * EditorPanel, every character re-rendered the entire right pane
 * (toolbar + Monaco wrapper + testcase cards) at ~5ms/char.
 */
export const useAutosaveStore = create<AutosaveState>((set) => ({
  status: "idle",
  setStatus: (status) =>
    // Skip redundant updates so a burst of keystrokes that are all
    // "saving" doesn't re-render the indicator per keypress.
    set((s) => (s.status === status ? s : { status })),
}));
