import { create } from "zustand";
import { persist } from "zustand/middleware";
import { createChromeStoragePersister } from "@/shared/services/storage/zustandChromeStorage";
import type { TestCase } from "@/features/testcases/types";

interface SeedCase {
  input: string;
  output: string;
}

interface TestcasesState {
  casesByTask: Record<string, TestCase[]>;
  seededTasks: Record<string, boolean>;
  getCases: (taskId: string) => TestCase[];
  /** Seeds a task's list from parsed sample tests, once, the first time it's visited. */
  seedIfNeeded: (taskId: string, seed: SeedCase[]) => void;
  addCase: (taskId: string) => void;
  updateCase: (
    taskId: string,
    id: string,
    patch: Partial<Pick<TestCase, "input" | "output">>
  ) => void;
  deleteCase: (taskId: string, id: string) => void;
  duplicateCase: (taskId: string, id: string) => void;
}

function makeId(): string {
  return crypto.randomUUID();
}

/**
 * Stable singleton for "task has no cases". getCases MUST NOT return a
 * fresh `[]` per call: zustand v5 selectors run through
 * useSyncExternalStore, which re-checks the snapshot by reference — a new
 * array every check reads as "store changed", force-updating in an
 * unbounded microtask-chained re-render loop that wedges the renderer
 * main thread and blocks the next same-origin navigation from committing
 * (the "hang when switching problems" bug).
 */
const NO_CASES: TestCase[] = [];

export const useTestcasesStore = create<TestcasesState>()(
  persist(
    (set, get) => ({
      casesByTask: {},
      seededTasks: {},

      getCases: (taskId) => get().casesByTask[taskId] ?? NO_CASES,

      seedIfNeeded: (taskId, seed) =>
        set((s) => {
          if (s.seededTasks[taskId] || seed.length === 0) return s;
          return {
            casesByTask: {
              ...s.casesByTask,
              [taskId]: seed.map((t) => ({ id: makeId(), ...t })),
            },
            seededTasks: { ...s.seededTasks, [taskId]: true },
          };
        }),

      addCase: (taskId) =>
        set((s) => ({
          casesByTask: {
            ...s.casesByTask,
            [taskId]: [
              ...(s.casesByTask[taskId] ?? []),
              { id: makeId(), input: "", output: "" },
            ],
          },
        })),

      updateCase: (taskId, id, patch) =>
        set((s) => ({
          casesByTask: {
            ...s.casesByTask,
            [taskId]: (s.casesByTask[taskId] ?? []).map((c) =>
              c.id === id ? { ...c, ...patch } : c
            ),
          },
        })),

      deleteCase: (taskId, id) =>
        set((s) => ({
          casesByTask: {
            ...s.casesByTask,
            [taskId]: (s.casesByTask[taskId] ?? []).filter((c) => c.id !== id),
          },
        })),

      duplicateCase: (taskId, id) =>
        set((s) => {
          const cases = s.casesByTask[taskId] ?? [];
          const index = cases.findIndex((c) => c.id === id);
          const original = cases[index];
          if (!original) return s;
          const copy: TestCase = { ...original, id: makeId() };
          const next = [...cases.slice(0, index + 1), copy, ...cases.slice(index + 1)];
          return { casesByTask: { ...s.casesByTask, [taskId]: next } };
        }),
    }),
    {
      name: "leetify:testcases",
      storage: createChromeStoragePersister(),
      // chrome.storage rehydration is async and races the first render's
      // seedIfNeeded: the default shallow merge would replace the WHOLE
      // casesByTask map with the persisted one (which doesn't yet contain
      // the task being viewed), wiping the just-seeded entry — after which
      // nothing re-seeds. Merge the per-task maps instead of replacing
      // them; persisted entries win per task (they may carry user edits).
      merge: (persisted, current) => {
        const p = (persisted ?? {}) as Partial<TestcasesState>;
        return {
          ...current,
          ...p,
          casesByTask: { ...current.casesByTask, ...p.casesByTask },
          seededTasks: { ...current.seededTasks, ...p.seededTasks },
        };
      },
    }
  )
);
