import { useEffect, useState } from "preact/hooks";
import { useTestcasesStore } from "@/state/testcasesStore";
import { useRunResultsStore } from "@/state/runResultsStore";
import type { TestCase } from "@/features/testcases/types";
import type { SampleTest } from "@/features/testcases/lib/parseSampleTests";
import type { CaseVerdict, RunCaseResult } from "@/extension/messaging/types";
import { Tabs } from "@/shared/components/Tabs";
import { IconButton } from "@/shared/components/IconButton";
import { PlayIcon, CopyIcon, TrashIcon, PlusIcon } from "@/shared/components/icons";
import { useDebouncedCallback } from "@/shared/hooks/useDebouncedCallback";

type PanelTab = "cases" | "result";

interface TestPanelProps {
  taskId: string;
  sampleTests: SampleTest[];
  onRun: () => void;
  running: boolean;
}

export function TestPanel({ taskId, sampleTests, onRun, running }: TestPanelProps) {
  const [tab, setTab] = useState<PanelTab>("cases");
  const [activeCase, setActiveCase] = useState(0);
  const cases = useTestcasesStore((s) => s.getCases(taskId));
  const seedIfNeeded = useTestcasesStore((s) => s.seedIfNeeded);
  const addCase = useTestcasesStore((s) => s.addCase);
  const updateCase = useTestcasesStore((s) => s.updateCase);
  const deleteCase = useTestcasesStore((s) => s.deleteCase);

  const runStatus = useRunResultsStore((s) => s.status);
  const lastRunTaskId = useRunResultsStore((s) => s.lastRunTaskId);
  const compileError = useRunResultsStore((s) => s.compileError);
  const infraError = useRunResultsStore((s) => s.infraError);
  const resultsByCase = useRunResultsStore((s) => s.resultsByCase);

  useEffect(() => {
    seedIfNeeded(taskId, sampleTests);
    // seedIfNeeded is a stable store action; re-seed decisions key on the
    // problem changing.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [taskId, sampleTests]);

  // Switch to the results tab the moment a run starts, LeetCode-style —
  // the store is global, but only one task's editor is ever mounted at a
  // time so this only fires for the run the user just triggered.
  useEffect(() => {
    if (runStatus === "running") setTab("result");
  }, [runStatus]);

  const safeIndex = Math.min(activeCase, Math.max(0, cases.length - 1));
  const current = cases[safeIndex];
  const hasRunForTask = lastRunTaskId === taskId;

  function handleAdd() {
    addCase(taskId);
    // Select the newly appended case.
    setActiveCase(cases.length);
  }

  function handleDelete(id: string) {
    deleteCase(taskId, id);
    setActiveCase((i) => Math.max(0, i - 1));
  }

  return (
    <div className="flex h-full flex-col bg-bg-raised">
      <div className="sticky top-0 z-10 shrink-0 border-b border-border-subtle px-4">
        <Tabs
          tabs={[
            { id: "cases", label: "Testcase" },
            { id: "result", label: "Test Result" },
          ]}
          activeId={tab}
          onChange={(id) => setTab(id as PanelTab)}
        />
      </div>

      {tab === "cases" ? (
        <div className="min-h-0 flex-1 overflow-auto p-4">
          {/* LeetCode-style numbered case pills + add. */}
          <div className="mb-3 flex flex-wrap items-center gap-2">
            {cases.map((c, i) => (
              <button
                key={c.id}
                onClick={() => setActiveCase(i)}
                className={`rounded-lg px-4 py-1.5 text-[13px] font-medium transition-all duration-100 active:scale-[0.97] ${
                  i === safeIndex
                    ? "bg-border text-fg"
                    : "bg-bg-overlay text-fg-muted hover:text-fg"
                }`}
              >
                Case {i + 1}
              </button>
            ))}
            <button
              aria-label="Add testcase"
              title="Add testcase"
              onClick={handleAdd}
              className="inline-flex h-8 w-8 items-center justify-center rounded-lg text-fg-muted transition-all duration-100 hover:bg-bg-overlay hover:text-fg active:scale-95"
            >
              <PlusIcon className="h-3.5 w-3.5" />
            </button>
          </div>

          {current ? (
            <TestCaseCard
              key={current.id}
              testCase={current}
              onChange={(patch) => updateCase(taskId, current.id, patch)}
              onDelete={() => handleDelete(current.id)}
            />
          ) : (
            <EmptyState
              title="No test cases yet"
              hint="Add one with the + button — sample tests seed automatically on problems that have them."
            />
          )}
        </div>
      ) : (
        <div className="min-h-0 flex-1 overflow-auto p-4">
          {runStatus === "running" ? (
            <div className="flex flex-col items-center gap-1.5 py-6 text-center">
              <p className="text-[13px] font-medium text-fg-muted">Running…</p>
              <p className="text-[12px] text-fg-subtle">
                Compiling and running against your test cases.
              </p>
            </div>
          ) : !hasRunForTask ? (
            <div className="flex min-h-full items-center justify-center">
              <EmptyState
                title="Run a test to see results here"
                hint="Click Run to compile and check your code against your test cases."
                icon
              />
            </div>
          ) : infraError ? (
            <div className="flex min-h-full items-center justify-center">
              <EmptyState title="Could not reach the judge" hint={infraError} icon />
            </div>
          ) : (
            <>
              <div className="mb-3 flex items-center justify-between">
                <div className="flex flex-wrap items-center gap-2">
                  {cases.map((c, i) => (
                    <button
                      key={c.id}
                      onClick={() => setActiveCase(i)}
                      className={`flex items-center gap-1.5 rounded-lg px-4 py-1.5 text-[13px] font-medium transition-all duration-100 active:scale-[0.97] ${
                        i === safeIndex
                          ? "bg-border text-fg"
                          : "bg-bg-overlay text-fg-muted hover:text-fg"
                      }`}
                    >
                      <VerdictDot verdict={resultsByCase[c.id]?.verdict} />
                      Case {i + 1}
                    </button>
                  ))}
                </div>
                <IconButton label="Run again" onClick={onRun} className="h-7 w-7">
                  <PlayIcon className="h-3.5 w-3.5" />
                </IconButton>
              </div>

              {compileError && (
                <div className="mb-3 rounded-lg border border-border-subtle bg-bg-overlay/40 p-3">
                  <p className="mb-1.5 text-[11px] font-medium uppercase tracking-[0.05em] text-fg-muted">
                    Compile error
                  </p>
                  <pre className="overflow-auto whitespace-pre-wrap font-mono text-[12.5px] leading-relaxed text-danger">
                    {compileError}
                  </pre>
                </div>
              )}

              {(() => {
                const currentResult = current ? resultsByCase[current.id] : undefined;
                return current && currentResult ? (
                  <ResultDetail testCase={current} result={currentResult} />
                ) : (
                  <EmptyState
                    title="No result for this case"
                    hint="This case wasn't included in the last run."
                  />
                );
              })()}
            </>
          )}
        </div>
      )}
    </div>
  );
}

const VERDICT_LABEL: Record<CaseVerdict, string> = {
  pass: "Pass",
  fail: "Fail",
  "runtime-error": "Runtime Error",
  timeout: "Timeout",
  "compile-error": "Compile Error",
  "infra-error": "Unavailable",
};

const VERDICT_DOT_COLOR: Record<CaseVerdict, string> = {
  pass: "bg-success",
  fail: "bg-danger",
  "runtime-error": "bg-danger",
  timeout: "bg-warning",
  "compile-error": "bg-fg-subtle",
  "infra-error": "bg-warning",
};

const VERDICT_TEXT_COLOR: Record<CaseVerdict, string> = {
  pass: "text-success",
  fail: "text-danger",
  "runtime-error": "text-danger",
  timeout: "text-warning",
  "compile-error": "text-fg-subtle",
  "infra-error": "text-warning",
};

function VerdictDot({ verdict }: { verdict?: CaseVerdict }) {
  if (!verdict) return null;
  return (
    <span
      aria-hidden="true"
      className={`h-1.5 w-1.5 rounded-full ${VERDICT_DOT_COLOR[verdict]}`}
    />
  );
}

function ResultDetail({ testCase, result }: { testCase: TestCase; result: RunCaseResult }) {
  if (result.verdict === "compile-error") {
    return (
      <p className="text-[13px] text-fg-muted">
        This case didn't run — the code failed to compile.
      </p>
    );
  }
  if (result.verdict === "infra-error") {
    return (
      <EmptyState
        title="Couldn't run this case"
        hint="The judge was unavailable for this case specifically. Try running again."
      />
    );
  }

  return (
    <div className="flex flex-col gap-3">
      <div className="flex items-center gap-2">
        <span className={`text-[12px] font-semibold ${VERDICT_TEXT_COLOR[result.verdict]}`}>
          {VERDICT_LABEL[result.verdict]}
        </span>
        {result.timeMs !== null && (
          <span className="text-[11px] tabular-nums text-fg-subtle">{result.timeMs}ms</span>
        )}
      </div>
      <ReadonlyField label="Input" value={testCase.input} />
      <ReadonlyField label="Expected Output" value={testCase.output} />
      {result.verdict === "timeout" ? (
        <p className="text-[12px] text-warning">Timed out — this case took too long to run.</p>
      ) : (
        <ReadonlyField
          label="Actual Output"
          value={result.actualOutput ?? ""}
          highlight={result.verdict === "fail" || result.verdict === "runtime-error"}
        />
      )}
      {result.stderr && <ReadonlyField label="Error Output" value={result.stderr} highlight />}
    </div>
  );
}

function ReadonlyField({
  label,
  value,
  highlight = false,
}: {
  label: string;
  value: string;
  highlight?: boolean;
}) {
  return (
    <div className="flex flex-col">
      <span className="mb-1.5 text-[11px] font-medium uppercase tracking-[0.05em] text-fg-muted">
        {label}
      </span>
      <pre
        className={`overflow-auto whitespace-pre-wrap rounded-md border px-3 py-2 font-mono text-[13px] leading-relaxed ${
          highlight
            ? "border-danger/40 bg-danger/5 text-fg"
            : "border-border-subtle bg-bg-base text-fg"
        }`}
      >
        {value || " "}
      </pre>
    </div>
  );
}

interface TestCaseCardProps {
  testCase: TestCase;
  onChange: (patch: Partial<Pick<TestCase, "input" | "output">>) => void;
  onDelete: () => void;
}

const FIELD_COMMIT_DELAY_MS = 400;

function TestCaseCard({ testCase, onChange, onDelete }: TestCaseCardProps) {
  const [input, setInput] = useState(testCase.input);
  const [output, setOutput] = useState(testCase.output);
  const commitInput = useDebouncedCallback(
    (value: string) => onChange({ input: value }),
    FIELD_COMMIT_DELAY_MS
  );
  const commitOutput = useDebouncedCallback(
    (value: string) => onChange({ output: value }),
    FIELD_COMMIT_DELAY_MS
  );

  function copyInput() {
    void navigator.clipboard?.writeText(input);
  }

  return (
    <div className="group relative rounded-lg border border-border-subtle bg-bg-overlay/40 p-3">
      {/* Card actions surface on hover, top-right. */}
      <div className="absolute right-2 top-2 z-10 flex items-center gap-0.5 opacity-0 transition-opacity duration-100 group-hover:opacity-100 group-focus-within:opacity-100">
        <IconButton label="Copy input" onClick={copyInput} className="h-7 w-7">
          <CopyIcon className="h-3.5 w-3.5" />
        </IconButton>
        <IconButton label="Delete testcase" onClick={onDelete} className="h-7 w-7">
          <TrashIcon className="h-3.5 w-3.5" />
        </IconButton>
      </div>
      <div className="flex flex-col gap-3">
        <TestCaseField
          label="Input"
          value={input}
          onInput={(v) => {
            setInput(v);
            commitInput(v);
          }}
        />
        <TestCaseField
          label="Expected Output"
          value={output}
          onInput={(v) => {
            setOutput(v);
            commitOutput(v);
          }}
        />
      </div>
    </div>
  );
}

function TestCaseField({
  label,
  value,
  onInput,
}: {
  label: string;
  value: string;
  onInput: (value: string) => void;
}) {
  return (
    <label className="flex flex-col">
      <span className="mb-1.5 text-[11px] font-medium uppercase tracking-[0.05em] text-fg-muted">
        {label}
      </span>
      <textarea
        value={value}
        onInput={(e) => onInput((e.target as HTMLTextAreaElement).value)}
        rows={2}
        spellcheck={false}
        className="resize-y rounded-md border border-border-subtle bg-bg-base px-3 py-2 font-mono text-[13px] leading-relaxed text-fg outline-none transition-colors duration-DEFAULT focus:border-accent"
      />
    </label>
  );
}

function EmptyState({
  title,
  hint,
  icon = false,
}: {
  title: string;
  hint: string;
  icon?: boolean;
}) {
  return (
    <div className="flex flex-col items-center gap-1.5 py-6 text-center">
      {icon && (
        <span className="mb-1 inline-flex h-9 w-9 items-center justify-center rounded-full bg-bg-overlay text-fg-subtle">
          <PlayIcon className="h-4 w-4" />
        </span>
      )}
      <p className="text-[13px] font-medium text-fg-muted">{title}</p>
      <p className="text-[12px] text-fg-subtle">{hint}</p>
    </div>
  );
}
