import { useMemo, useRef, useState } from "preact/hooks";
import { EditorToolbar } from "@/features/editor/components/EditorToolbar";
import { MonacoEditor } from "@/features/editor/components/MonacoEditor";
import { TestPanel } from "@/features/testcases/components/TestPanel";
import { parseSampleTests } from "@/features/testcases/lib/parseSampleTests";
import { useAutosave } from "@/features/editor/hooks/useAutosave";
import { STARTER_TEMPLATES } from "@/features/editor/lib/starterTemplates";
import { useVerticalResize } from "@/features/layout/hooks/useVerticalResize";
import { snapshotKey, useEditorStore } from "@/state/editorStore";
import { useWorkspaceStore } from "@/state/workspaceStore";
import { useTestcasesStore } from "@/state/testcasesStore";
import { useRunResultsStore } from "@/state/runResultsStore";
import { navigateToNativeSubmit } from "@/extension/content/submitFlow";
import { getCsesSessionHash } from "@/shared/lib/sessionHash";
import type { RunRequest, RunResponse } from "@/extension/messaging/types";

interface EditorPanelProps {
  taskId: string;
  problemNode: Element | null;
  isLoggedIn: boolean;
}

const RUN_BANNER_DURATION_MS = 3000;

export function EditorPanel({ taskId, problemNode, isLoggedIn }: EditorPanelProps) {
  const language = useEditorStore((s) => s.language);
  const setLanguage = useEditorStore((s) => s.setLanguage);
  const fontSize = useEditorStore((s) => s.fontSize);
  const setFontSize = useEditorStore((s) => s.setFontSize);
  // Subscribe to the snapshot itself (stable store reference, so this is
  // loop-safe) rather than reading through a getter — the panel must
  // re-render when async hydration lands with previously saved code.
  const snapshot = useEditorStore(
    (s) => s.snapshots[snapshotKey(taskId, language)]
  );

  const { save } = useAutosave(taskId, language);
  // No snapshot means the user never wrote anything for this
  // task+language: start from the boilerplate. An intentionally emptied
  // editor (snapshot with code === "") stays empty — no re-injection.
  const code = snapshot?.code ?? STARTER_TEMPLATES[language];
  const theme = useWorkspaceStore((s) => s.theme);
  const testPanelHeightPx = useWorkspaceStore((s) => s.testPanelHeightPx);
  const setTestPanelHeightPx = useWorkspaceStore((s) => s.setTestPanelHeightPx);
  const sampleTests = useMemo(() => parseSampleTests(problemNode), [problemNode]);

  const containerRef = useRef<HTMLDivElement | null>(null);
  const { dragHeight, startDragging } = useVerticalResize({
    containerRef,
    onCommit: setTestPanelHeightPx,
  });
  const panelHeightPx = dragHeight ?? testPanelHeightPx;

  const [banner, setBanner] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);
  const [running, setRunning] = useState(false);
  const cases = useTestcasesStore((s) => s.getCases(taskId));
  const startRun = useRunResultsStore((s) => s.startRun);
  const setRunResults = useRunResultsStore((s) => s.setResults);
  const setRunInfraError = useRunResultsStore((s) => s.setInfraError);

  function showBanner(message: string, durationMs = RUN_BANNER_DURATION_MS) {
    setBanner(message);
    setTimeout(
      () => setBanner((current) => (current === message ? null : current)),
      durationMs
    );
  }

  async function handleRun() {
    if (!isLoggedIn) {
      // Defense in depth — the toolbar already disables Run in this
      // state, but this guards direct calls (e.g. TestPanel's re-run
      // button) too.
      showBanner("Log in to CSES to use Run.");
      return;
    }
    if (cases.length === 0) {
      showBanner("Add a test case first — there's nothing to run against.");
      return;
    }
    setRunning(true);
    startRun(taskId);
    try {
      const sessionHash = await getCsesSessionHash();
      const request: RunRequest = {
        type: "run-test-cases",
        taskId,
        language,
        code,
        cases: cases.map((c) => ({ caseId: c.id, input: c.input, expectedOutput: c.output })),
        sessionHash,
      };
      const response = (await chrome.runtime.sendMessage(request)) as RunResponse;
      setRunResults(taskId, response.compileError, response.results);
    } catch {
      // chrome.runtime.sendMessage rejects (rather than resolving falsy)
      // when the background worker is unreachable or the extension
      // context was invalidated (e.g. mid-reload) — never show a fake
      // per-case verdict for that.
      setRunInfraError(taskId, "Could not reach the judge — try again in a moment.");
    } finally {
      setRunning(false);
    }
  }

  async function handleSubmit() {
    setSubmitting(true);
    try {
      const ok = await navigateToNativeSubmit({
        taskId,
        code,
        language,
        createdAt: Date.now(),
      });
      if (!ok) {
        showBanner("Couldn't find CSES's Submit tab — are you logged in?");
      }
      // On success the page is navigating away; nothing left to set.
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <div ref={containerRef} className="flex h-full flex-col bg-bg-raised">
      <EditorToolbar
        language={language}
        onLanguageChange={setLanguage}
        fontSize={fontSize}
        onFontSizeChange={setFontSize}
        onRun={handleRun}
        onSubmit={handleSubmit}
        isLoggedIn={isLoggedIn}
        running={running}
        submitting={submitting}
      />
      {banner && (
        <div className="border-b border-border-subtle bg-bg-overlay px-4 py-1.5 text-[12px] text-fg-muted">
          {banner}
        </div>
      )}
      <div className="relative min-h-0 flex-1">
        <MonacoEditor
          value={code}
          language={language}
          fontSize={fontSize}
          theme={theme}
          onChange={save}
        />
        {/* Subtle credit, overlaid so it costs no editor height. Sits
            left of Monaco's own scrollbar/minimap gutter, non-interactive
            except for the link itself. */}
        <div className="pointer-events-none absolute bottom-1.5 right-4 select-none text-[11px] text-fg-subtle/60">
          Made with{" "}
          <span aria-hidden="true" className="text-danger/70">
            ♥
          </span>{" "}
          by{" "}
          <a
            href="https://github.com/Navoren"
            target="_blank"
            rel="noreferrer"
            className="pointer-events-auto text-fg-subtle/60 underline decoration-dotted underline-offset-2 transition-colors duration-100 hover:text-accent"
          >
            @navoren
          </a>
        </div>
      </div>
      {/* Horizontal drag handle: fixed 4px hit strip, inner line thickens
          to fill it (and picks up the accent) on hover — no layout shift. */}
      <div
        role="separator"
        aria-orientation="horizontal"
        aria-label="Resize console panel"
        onPointerDown={(e) => startDragging(e as unknown as PointerEvent)}
        className="group relative flex h-1 shrink-0 cursor-row-resize flex-col items-stretch justify-center"
      >
        <div className="h-px bg-border transition-all duration-100 group-hover:h-full group-hover:bg-accent" />
        <div className="absolute inset-x-0 -top-1 -bottom-1" />
      </div>
      <div style={{ height: `${panelHeightPx}px` }} className="shrink-0">
        <TestPanel
          taskId={taskId}
          sampleTests={sampleTests}
          onRun={handleRun}
          running={running}
        />
      </div>
    </div>
  );
}
