import type { JSX } from "preact";

interface SelectOption<T extends string> {
  value: T;
  label: string;
}

interface SelectProps<T extends string> {
  value: T;
  options: SelectOption<T>[];
  onChange: (value: T) => void;
  ariaLabel: string;
  className?: string;
}

export function Select<T extends string>({
  value,
  options,
  onChange,
  ariaLabel,
  className = "",
}: SelectProps<T>) {
  function handleChange(event: JSX.TargetedEvent<HTMLSelectElement>) {
    onChange(event.currentTarget.value as T);
  }

  return (
    <select
      aria-label={ariaLabel}
      value={value}
      onChange={handleChange}
      className={`h-8 cursor-pointer rounded-md border border-transparent bg-bg-overlay px-2.5 text-[13px] text-fg outline-none transition-colors duration-DEFAULT hover:border-border focus:border-accent ${className}`}
    >
      {options.map((option) => (
        <option key={option.value} value={option.value}>
          {option.label}
        </option>
      ))}
    </select>
  );
}
