import type { TitleBlockMeta } from "@/extension/content/findProblemContent";

interface WorkspaceHeaderProps {
  meta: TitleBlockMeta;
}

/**
 * Slim dark header replacing CSES's white `.title-block` band: course
 * breadcrumb + problem title on the left, the original Task/Submit/
 * Results links restyled as ghost pills on the right. The links are
 * CSES's real hrefs — Submit/Results still navigate natively.
 */
export function WorkspaceHeader({ meta }: WorkspaceHeaderProps) {
  return (
    <div className="flex h-11 shrink-0 items-center justify-between gap-4 border-b border-border-subtle bg-bg-raised px-4">
      <div className="flex min-w-0 items-baseline gap-2">
        {meta.courseLabel && meta.courseHref && (
          <>
            <a
              href={meta.courseHref}
              className="shrink-0 text-[12px] text-fg-muted transition-colors duration-100 hover:text-fg"
            >
              {meta.courseLabel}
            </a>
            <span aria-hidden="true" className="text-[12px] text-fg-subtle">
              /
            </span>
          </>
        )}
        <h1 className="truncate text-[14px] font-semibold text-fg">
          {meta.title}
        </h1>
      </div>
      <nav className="flex shrink-0 items-center gap-1">
        {meta.navLinks.map((link) => (
          <a
            key={link.href}
            href={link.href}
            aria-current={link.current ? "page" : undefined}
            className={`rounded-md px-2.5 py-1 text-[12px] font-medium transition-colors duration-100 ${
              link.current
                ? "bg-bg-overlay text-fg"
                : "text-fg-muted hover:bg-bg-overlay hover:text-fg"
            }`}
          >
            {link.label}
          </a>
        ))}
      </nav>
    </div>
  );
}
