import type { ComponentChildren, JSX } from "preact";

type Variant = "primary" | "ghost" | "subtle";

interface ButtonProps
  extends Omit<JSX.HTMLAttributes<HTMLButtonElement>, "size"> {
  variant?: Variant;
  children: ComponentChildren;
  disabled?: boolean;
}

const VARIANT_CLASSES: Record<Variant, string> = {
  // Solid accent CTA: white text, soft accent glow on hover.
  primary:
    "bg-accent text-white hover:bg-accent-hover hover:shadow-[0_2px_10px_rgb(var(--color-accent)/0.35)]",
  ghost: "text-fg-muted hover:bg-bg-overlay hover:text-fg",
  // Dark-filled secondary (Run): panel-layer fill, brightens on hover.
  subtle: "bg-bg-overlay text-fg hover:bg-border",
};

export function Button({
  variant = "subtle",
  className = "",
  children,
  ...rest
}: ButtonProps) {
  return (
    <button
      className={`inline-flex items-center gap-1.5 rounded-md px-3.5 py-1.5 text-[13px] font-medium transition-all duration-100 active:scale-[0.97] disabled:cursor-not-allowed disabled:opacity-50 ${VARIANT_CLASSES[variant]} ${className}`}
      {...rest}
    >
      {children}
    </button>
  );
}
