/**
 * Locates the CSES task page's main content element so it can be relocated
 * into our split-pane layout instead of being duplicated or hidden.
 *
 * CSES wraps page content in `div.content`, alongside a `div.nav.sidebar`
 * containing the topic's problem list and a "Your submissions" section
 * separated by an `<hr>`. This selector is unverified against markup CSES
 * hasn't shown us yet — if it changes, this returns null and the
 * workspace falls back to a floating overlay (see mount.tsx) rather than
 * breaking the page.
 */
export function findProblemContent(): Element | null {
  return document.querySelector(".content");
}

export interface PageNavLink {
  label: string;
  href: string;
  current: boolean;
}

export interface TitleBlockMeta {
  courseLabel: string | null;
  courseHref: string | null;
  title: string;
  navLinks: PageNavLink[];
}

/**
 * Reads CSES's `.title-block` (course link, problem title, and the
 * Task/Submit/Results nav) so the white navigation band can be removed
 * and its data re-rendered inside the workspace's own dark header.
 * Logged-out pages carry Task/Statistics; logged-in task pages carry
 * Task/Submit/Results — we re-render whatever is actually there.
 */
export function extractTitleBlock(): TitleBlockMeta | null {
  const block = document.querySelector(".navigation .title-block");
  if (!block) return null;
  const courseLink = block.querySelector<HTMLAnchorElement>("h3 a");
  const title =
    block.querySelector("h1")?.textContent?.trim() || document.title;
  const navLinks = Array.from(
    block.querySelectorAll<HTMLAnchorElement>("ul.nav a")
  ).map((a) => ({
    label: a.textContent?.trim() ?? "",
    href: a.href,
    current: a.classList.contains("current"),
  }));
  return {
    courseLabel: courseLink?.textContent?.trim() ?? null,
    courseHref: courseLink?.href ?? null,
    title,
    navLinks,
  };
}

export function findSidebarContent(): Element | null {
  return document.querySelector(".content-wrapper > .nav.sidebar");
}

export interface SidebarSections {
  topicLabel: string;
  topicEl: HTMLElement;
  submissionsEl: HTMLElement;
}

/**
 * Splits the sidebar's real DOM nodes (not copies — moving them preserves
 * CSES's own click handlers/state) into a "topic list" section and a
 * "your submissions" section, using the `<hr>` between them as the
 * boundary. The topic label is read from the section's own `<h4>` (e.g.
 * "Introductory Problems") rather than hardcoded, since it varies by
 * course/section.
 */
export function splitSidebarSections(sidebar: Element): SidebarSections {
  const topicEl = document.createElement("div");
  topicEl.className = "topic-list";
  const submissionsEl = document.createElement("div");
  submissionsEl.className = "submissions-list";
  let target = topicEl;

  for (const child of Array.from(sidebar.children)) {
    if (child.tagName === "HR") {
      target = submissionsEl;
      continue;
    }
    target.appendChild(child);
  }

  const topicLabel = topicEl.querySelector("h4")?.textContent?.trim() || "Problems";
  return { topicLabel, topicEl, submissionsEl };
}
