import { useState } from "preact/hooks";
import { NativeNodeHost } from "@/shared/components/NativeNodeHost";
import { Tabs } from "@/shared/components/Tabs";

interface ProblemPaneProps {
  problemNode: Element | null;
  topicLabel: string;
  topicNode: Element | null;
  submissionsNode: Element | null;
}

export function ProblemPane({
  problemNode,
  topicLabel,
  topicNode,
  submissionsNode,
}: ProblemPaneProps) {
  const tabs = [
    { id: "problem", label: "Description" },
    ...(topicNode ? [{ id: "topic", label: topicLabel }] : []),
    ...(submissionsNode ? [{ id: "submissions", label: "Submissions" }] : []),
  ];
  const [activeId, setActiveId] = useState(tabs[0]?.id ?? "problem");

  return (
    <div className="problem-pane flex h-full flex-col">
      <div className="sticky top-0 z-10 shrink-0 border-b border-border-subtle bg-bg-raised px-5">
        <Tabs tabs={tabs} activeId={activeId} onChange={setActiveId} />
      </div>
      {/* Own scroll region, independent of the editor pane. */}
      <div className="min-h-0 flex-1 overflow-auto px-6 py-5">
        {/*
          Only the active tab's node is inserted into the DOM. CSES's own
          submission history can be large; rendering it hidden-but-present
          would still cost layout/style on every page load.
        */}
        {activeId === "problem" && <NativeNodeHost node={problemNode} />}
        {activeId === "topic" && <NativeNodeHost node={topicNode} />}
        {activeId === "submissions" && <NativeNodeHost node={submissionsNode} />}
      </div>
    </div>
  );
}
