import type { ComponentChildren, JSX } from "preact";

interface IconButtonProps
  extends Omit<JSX.HTMLAttributes<HTMLButtonElement>, "size"> {
  children: ComponentChildren;
  label: string;
  active?: boolean;
  disabled?: boolean;
}

/** Ghost icon button: circular hit area, background appears on hover only. */
export function IconButton({
  children,
  label,
  active = false,
  className = "",
  ...rest
}: IconButtonProps) {
  return (
    <button
      aria-label={label}
      title={label}
      className={`inline-flex h-8 w-8 items-center justify-center rounded-full text-fg-muted transition-all duration-100 hover:bg-bg-overlay hover:text-fg active:scale-95 disabled:cursor-not-allowed disabled:opacity-40 ${
        active ? "bg-bg-overlay text-fg" : ""
      } ${className}`}
      {...rest}
    >
      {children}
    </button>
  );
}
