import { useEffect, useMemo, useRef } from "preact/hooks";
import { useEditorStore } from "@/state/editorStore";
import { useAutosaveStore } from "@/state/autosaveStore";
import type { LanguageId } from "@/shared/types/language";

const AUTOSAVE_DELAY_MS = 600;
const SAVED_INDICATOR_MS = 1200;

/**
 * Debounces writes of editor content into the persisted editor store.
 * Status goes to the separate autosaveStore (see its comment for why)
 * rather than local React state, so calling `save` per keystroke does
 * not re-render the editor pane.
 */
export function useAutosave(taskId: string, language: LanguageId) {
  const setCode = useEditorStore((s) => s.setCode);
  const timerRef = useRef<ReturnType<typeof setTimeout>>();
  const savedIndicatorRef = useRef<ReturnType<typeof setTimeout>>();

  useEffect(() => {
    return () => {
      clearTimeout(timerRef.current);
      clearTimeout(savedIndicatorRef.current);
    };
  }, []);

  const save = useMemo(
    () => (code: string) => {
      const { setStatus } = useAutosaveStore.getState();
      setStatus("saving");
      clearTimeout(timerRef.current);
      timerRef.current = setTimeout(() => {
        setCode(taskId, language, code);
        setStatus("saved");
        clearTimeout(savedIndicatorRef.current);
        savedIndicatorRef.current = setTimeout(
          () => setStatus("idle"),
          SAVED_INDICATOR_MS
        );
      }, AUTOSAVE_DELAY_MS);
    },
    [taskId, language, setCode]
  );

  return { save };
}
