import type { ComponentChildren } from "preact";
import { useRef } from "preact/hooks";
import { usePanelResize } from "@/features/layout/hooks/usePanelResize";

interface SplitPaneProps {
  left: ComponentChildren;
  right: ComponentChildren;
  splitPercent: number;
  onSplitChange: (percent: number) => void;
}

export function SplitPane({
  left,
  right,
  splitPercent,
  onSplitChange,
}: SplitPaneProps) {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const { dragPercent, startDragging } = usePanelResize({
    containerRef,
    onCommit: onSplitChange,
  });
  const percent = dragPercent ?? splitPercent;

  return (
    <div ref={containerRef} className="flex h-full w-full min-w-0 bg-bg-base">
      <div
        className="h-full min-w-0 overflow-hidden"
        style={{ width: `${percent}%` }}
      >
        {left}
      </div>
      {/*
        Fixed 4px hit strip so hovering doesn't shift layout: a thin inner
        line thickens to fill the strip (and picks up the accent) on hover.
      */}
      <div
        role="separator"
        aria-orientation="vertical"
        aria-label="Resize panels"
        tabIndex={0}
        onPointerDown={(e) => startDragging(e as unknown as PointerEvent)}
        className="group relative flex w-1 shrink-0 cursor-col-resize items-stretch justify-center"
      >
        <div className="w-px bg-border transition-all duration-100 group-hover:w-full group-hover:bg-accent" />
        <div className="absolute inset-y-0 -left-1 -right-1" />
      </div>
      <div
        className="h-full min-w-0 flex-1 overflow-hidden"
        style={{ width: `${100 - percent}%` }}
      >
        {right}
      </div>
    </div>
  );
}
