/**
 * Extracts the CSES task id from a problem URL. CSES serves the same task
 * viewer under multiple path prefixes — /problemset/task/1068 for the
 * public set, /<course-alias>/task/1068 (e.g. /alon/task/1688) for
 * course-specific mirrors — so this matches on "/task/<id>" regardless of
 * what precedes it.
 */
export function getTaskIdFromUrl(url: string = location.href): string | null {
  const match = url.match(/\/task\/(\d+)/);
  return match?.[1] ?? null;
}
