import { render } from "preact";
import { Workspace } from "@/features/layout/components/Workspace";
import {
  extractTitleBlock,
  findProblemContent,
  findSidebarContent,
  splitSidebarSections,
} from "@/extension/content/findProblemContent";
import { rememberSubmitHref } from "@/extension/content/submitFlow";
import { getTaskIdFromUrl } from "@/shared/lib/problem";
import {
  useWorkspaceStore,
  waitForWorkspaceHydration,
} from "@/state/workspaceStore";
import stylesUrl from "@/ui/theme.css?url";

const HOST_ID = "leetify-cses-host";

export async function mountWorkspace() {
  const taskId = getTaskIdFromUrl();
  if (!taskId) return;
  if (document.getElementById(HOST_ID)) return;
  // A page with a file input is CSES's submit form, not a problem
  // statement — mounting the workspace there would relocate its (very
  // different) content into our layout and break it. See submitFlow.ts,
  // which handles that page instead.
  if (document.querySelector('input[type="file"]')) return;

  // The on/off switch lives in persisted state; respect it before
  // touching the page at all.
  await waitForWorkspaceHydration();
  if (!useWorkspaceStore.getState().enabled) return;

  const problemNode = findProblemContent();
  const sidebarNode = findSidebarContent();
  // Read the title/nav metadata before we tear the band out of the page.
  const pageMeta = extractTitleBlock();
  const sections = sidebarNode ? splitSidebarSections(sidebarNode) : null;
  // splitSidebarSections moves the sidebar's real children out into new
  // wrapper elements, leaving the original (now-empty) node behind —
  // remove it so it doesn't sit as a blank column next to the workspace.
  sidebarNode?.remove();

  const host = document.createElement("div");
  host.id = HOST_ID;
  // The host replaces CSES's `.content` inside `.content-wrapper`, which
  // is `display: flex` (cses.css). Without explicit sizing it becomes a
  // flex item with auto basis, so its width would track the intrinsic
  // width of whatever the active tab renders — visibly shrinking or
  // growing as the user switches tabs. Pin it to the full row.
  host.style.flex = "1 1 100%";
  host.style.width = "100%";
  host.style.minWidth = "0";
  const shadowRoot = host.attachShadow({ mode: "open" });

  const stylesheet = document.createElement("link");
  stylesheet.rel = "stylesheet";
  // vite.config.ts rewrites built asset URLs to chrome.runtime.getURL(...)
  // calls at build time, so stylesUrl already resolves to the correct
  // chrome-extension:// origin here.
  stylesheet.href = stylesUrl;
  shadowRoot.appendChild(stylesheet);

  const appRoot = document.createElement("div");
  appRoot.id = "leetify-cses-root";
  shadowRoot.appendChild(appRoot);

  applyTheme(appRoot);
  useWorkspaceStore.subscribe((state) => {
    appRoot.dataset.theme = state.theme;
  });

  if (problemNode?.parentElement) {
    problemNode.parentElement.replaceChild(host, problemNode);
  } else {
    document.body.appendChild(host);
  }

  // cses.css caps the whole content area at `.skeleton { max-width: 960px;
  // margin: auto }`, which strands the workspace in the middle of wide
  // windows with white gutters either side. A LeetCode-style workspace
  // should fill the viewport; lift the cap only when we actually mount so
  // disabled/native pages keep CSES's own layout.
  const skeleton = document.querySelector<HTMLElement>(".skeleton");
  if (skeleton) {
    skeleton.style.maxWidth = "none";
    // `.skeleton { margin: 8px auto }` leaves a white sliver above the
    // workspace once the navigation band is gone; sit flush under the
    // dark CSES header instead.
    skeleton.style.margin = "0";
  }

  // The white title band (course link, h1 title, Task/Submit/Results) is
  // re-rendered inside the workspace's own header — remove the original
  // only when we have its data, so a markup change degrades to keeping
  // CSES's band rather than losing the title entirely.
  if (pageMeta) {
    // Capture the real Submit href before removing the node it lives on —
    // submitFlow.ts needs this at click time, long after this node is
    // gone (see rememberSubmitHref's own comment for the regression this
    // fixes).
    const submitLink = pageMeta.navLinks.find(
      (l) => l.label.trim().toLowerCase() === "submit"
    );
    rememberSubmitHref(submitLink?.href ?? null);
    document.querySelector(".navigation")?.remove();
  }

  // `position: sticky` only pins once scrolled *past* this point — at the
  // initial scroll position (the common case: a user just landed on the
  // page) the workspace still sits at its natural offset below CSES's own
  // header/nav, so a flat 100vh height overflows the viewport by that
  // offset. Measuring it and sizing to the actual remaining space makes
  // the workspace fit fully in view immediately, not just after scrolling.
  const topOffsetPx = host.getBoundingClientRect().top;

  render(
    <Workspace
      taskId={taskId}
      problemNode={problemNode}
      topicLabel={sections?.topicLabel ?? "Problems"}
      topicNode={sections?.topicEl ?? null}
      submissionsNode={sections?.submissionsEl ?? null}
      pageMeta={pageMeta}
      topOffsetPx={topOffsetPx}
    />,
    appRoot
  );
}

function applyTheme(appRoot: HTMLElement) {
  appRoot.dataset.theme = useWorkspaceStore.getState().theme;
}
