import { useCallback, useRef, useState } from "preact/hooks";
import { TEST_PANEL_MAX_HEIGHT_PX, TEST_PANEL_MIN_HEIGHT_PX } from "@/ui/tokens";

interface UseVerticalResizeArgs {
  containerRef: { current: HTMLElement | null };
  /** Fires once, at drag end — not per pointermove — since onCommit is expected to persist. */
  onCommit: (heightPx: number) => void;
}

/**
 * Drag-to-resize for a bottom panel whose height is measured up from its
 * container's bottom edge. Same live-value/commit-on-end split as
 * usePanelResize (see its comments for the storage-write rationale).
 */
export function useVerticalResize({ containerRef, onCommit }: UseVerticalResizeArgs) {
  const [dragHeight, setDragHeight] = useState<number | null>(null);
  const dragHeightRef = useRef<number | null>(null);
  const rafRef = useRef<number | null>(null);
  const onCommitRef = useRef(onCommit);
  onCommitRef.current = onCommit;

  const handlePointerMove = useCallback(
    (event: PointerEvent) => {
      if (!containerRef.current) return;
      const rect = containerRef.current.getBoundingClientRect();
      const heightFromBottom = rect.bottom - event.clientY;
      const clamped = Math.min(
        TEST_PANEL_MAX_HEIGHT_PX,
        Math.max(TEST_PANEL_MIN_HEIGHT_PX, heightFromBottom)
      );
      dragHeightRef.current = clamped;
      if (rafRef.current !== null) return;
      rafRef.current = requestAnimationFrame(() => {
        rafRef.current = null;
        setDragHeight(dragHeightRef.current);
      });
    },
    [containerRef]
  );

  const stopDragging = useCallback(() => {
    document.removeEventListener("pointermove", handlePointerMove);
    document.removeEventListener("pointerup", stopDragging);
    document.body.style.cursor = "";
    document.body.style.userSelect = "";
    if (rafRef.current !== null) {
      cancelAnimationFrame(rafRef.current);
      rafRef.current = null;
    }
    if (dragHeightRef.current !== null) {
      onCommitRef.current(dragHeightRef.current);
    }
    dragHeightRef.current = null;
    setDragHeight(null);
  }, [handlePointerMove]);

  const startDragging = useCallback(
    (event: PointerEvent) => {
      event.preventDefault();
      document.addEventListener("pointermove", handlePointerMove);
      document.addEventListener("pointerup", stopDragging);
      document.body.style.cursor = "row-resize";
      document.body.style.userSelect = "none";
    },
    [handlePointerMove, stopDragging]
  );

  return { dragHeight, startDragging };
}
